from collections import OrderedDict


class Policy:
    def __init__(self, capacity_bytes: int):
        self.capacity_bytes = max(0, capacity_bytes)
        self.probation = OrderedDict()
        self.protected = OrderedDict()
        self.used_bytes = 0
        self.protected_bytes = 0
        self.protected_limit = (self.capacity_bytes * 3) // 4

    def _demote_oldest_protected(self):
        if not self.protected:
            return
        key, size = self.protected.popitem(last=False)
        self.protected_bytes -= size
        self.probation[key] = size

    def _trim_protected(self):
        while self.protected and self.protected_bytes > self.protected_limit:
            self._demote_oldest_protected()

    def _evict_oldest_probation(self, evicted):
        if not self.probation:
            return False
        key, size = self.probation.popitem(last=False)
        self.used_bytes -= size
        evicted.append(key)
        return True

    def access(self, key: int, size: int, now: int) -> list[int]:
        if key in self.protected:
            stored_size = self.protected.pop(key)
            self.protected[key] = stored_size
            return []

        if key in self.probation:
            stored_size = self.probation.pop(key)
            if self.protected_limit > 0:
                self.protected[key] = stored_size
                self.protected_bytes += stored_size
                self._trim_protected()
            else:
                self.probation[key] = stored_size
            return []

        if size > self.capacity_bytes or size < 0:
            return []

        evicted = []
        while self.used_bytes + size > self.capacity_bytes:
            if not self._evict_oldest_probation(evicted):
                if self.protected:
                    self._demote_oldest_protected()
                else:
                    break

        self.probation[key] = size
        self.used_bytes += size
        return evicted
